import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import * as api from "@/lib/api";
import { must } from "@/lib/backend";
import { readServiceCard } from "@/lib/reads";

import Hero from "@/components/common/hero";
import ServiceCard from "@/components/common/service-card";

export const metadata: Metadata = { title: "chair" };

export default function Page() {
    return (
        <main className="flex flex-1 flex-col">
            <Suspense fallback={<p className="px-4 py-16 text-center text-muted-foreground">Loading…</p>}>
                <Sections />
            </Suspense>
        </main>
    );
}

// Sections streams in after the page's shell.
async function Sections() {
    await connection();
    const loaded = await must(api.services.list());
    const props2 = await Promise.all(loaded.map(readServiceCard));
    return (
        <>
            <Hero />
            {props2.length === 0 ? (
                <p className="mx-auto w-full max-w-5xl px-4 py-16 text-center text-muted-foreground sm:px-6">{"No services yet."}</p>
            ) : (
                <section className="mx-auto grid w-full max-w-5xl gap-6 px-4 py-8 sm:grid-cols-2 sm:px-6 lg:grid-cols-3 has-[>[data-shape=row]]:max-w-3xl has-[>[data-shape=row]]:grid-cols-1 has-[>[data-shape=row]]:gap-4">
                    {props2.map((item) => (
                        <ServiceCard key={item.service.id} {...item} />
                    ))}
                </section>
            )}
        </>
    );
}
